-- Hand-authored (not generated by `prisma migrate dev`): the Prisma engine
-- binaries needed to tool-generate a diff are unreachable from the build
-- environment. Executed against PostgreSQL 16 on top of the real init
-- migration, including the case where the column already exists.
--
-- The isPlatformAdmin column was never part of any earlier migration, so it
-- is added here when missing. When it is added, only the earliest-created
-- admin (the bootstrap account) is made a platform admin; every other
-- existing admin starts with no cross-tenant access and can be promoted
-- with: npx tsx scripts/create-admin.ts <email> "<password>" --platform-admin
-- If the column already exists, existing values are left untouched.
--
-- This does NOT create the tenant/marketing tables (Tenant, TenantMember,
-- MarketingProject, SocialConnection, ScheduledPost, and 11 other models).
-- Generate that migration with `npx prisma migrate dev` against a real
-- database before deploying. See SETUP_GUIDE.md.

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = current_schema()
      AND table_name = 'admin_users'
      AND column_name = 'isPlatformAdmin'
  ) THEN
    ALTER TABLE "admin_users" ADD COLUMN "isPlatformAdmin" BOOLEAN NOT NULL DEFAULT false;
    UPDATE "admin_users" SET "isPlatformAdmin" = true
    WHERE "id" = (SELECT "id" FROM "admin_users" ORDER BY "createdAt" ASC, "id" ASC LIMIT 1);
  END IF;
END $$;

ALTER TABLE "admin_users" ALTER COLUMN "isPlatformAdmin" SET DEFAULT false;
